 "cards": [
  {
   "id": "s1",
   "type": "text",
   "front": "Define stressor, stress, hardiness and resilience.",
   "back": "Stressor: a condition challenging homeostasis. Stress: the physiological or psychological response to it. Hardiness: coping with acute or chronic stress and staying healthy. Resilience: bouncing back from the initial negative effects."
  },
  {
   "id": "s2",
   "type": "text",
   "front": "Eustress versus distress.",
   "back": "Eustress enhances function. Distress is often persistent and not resolved by coping or adaptation."
  },
  {
   "id": "s3",
   "type": "text",
   "front": "What is the general adaptation syndrome?",
   "back": "Hans Selye, 1936: stress is the nonspecific response of the body to any demand, running through three stages. The alarm reaction triad: an enlarged adrenal cortex discharging lipid granules; involution of the thymus, spleen and lymph nodes; deep bleeding ulcers in the stomach and duodenum."
  },
  {
   "id": "s4",
   "type": "text",
   "front": "Why does stress matter clinically?",
   "back": "Up to 70 percent of primary care visits are estimated to be for stress and lifestyle problems, and the link between mental stress and physical disease is complex and multifactorial. The concept of allostasis and allostatic load describes the cost of repeated adaptation."
  },
  {
   "id": "s5",
   "type": "text",
   "front": "Physical versus psychological stressors.",
   "back": "Physical: actual disturbances of physiology, such as haemorrhage and infection, processed by the brainstem and hypothalamus, needing an immediate, reflex-like response. Psychological: anticipated threats, such as aversive stimuli, predator cues or unmet drives, engaging the PFC, amygdala, hippocampus, PVN, VTA and nucleus accumbens as well as SN, SAM and HPA."
  },
  {
   "id": "s6",
   "type": "text",
   "front": "Give the two phases of the stress response.",
   "back": "First: autonomic activation (SN and SAM), rapid, bringing alertness, appraisal and decision making. Second: the hormonal HPA axis, sluggish, but amplified and protracted."
  },
  {
   "id": "h1",
   "type": "image",
   "target": "hypothalamus",
   "front": "Which structure is at the arrow, and what does it release in stress?",
   "back": "The hypothalamus: its paraventricular nucleus releases CRH."
  },
  {
   "id": "s7",
   "type": "text",
   "front": "Describe acute stress.",
   "back": "Short (under 2 days to 4 weeks), triggering fight or flight: SN, SAM and HPA are activated and the parasympathetic system diminished. Removing the stressor should restore normality quickly, though sometimes delayed. Examples: danger, trauma, accidents, disasters, crime, witnessing violence."
  },
  {
   "id": "s8",
   "type": "text",
   "front": "List the four major fight-or-flight responses.",
   "back": "1. Stimulated mental activity. 2. Epinephrine release from the adrenal medulla. 3. Cardiovascular: faster, stronger heart, higher cardiac output, arteriolar constriction in many areas, higher pressure, more blood to muscle and heart, less to gut and kidneys. 4. Metabolic: higher metabolic rate, blood glucose, glycolysis and coagulation rate."
  },
  {
   "id": "s9",
   "type": "text",
   "front": "Name the adrenal zones and their hormones.",
   "back": "Zona glomerulosa: mineralocorticoids such as aldosterone. Zona fasciculata: glucocorticoids and androgens. Zona reticularis: androgens and glucocorticoids. Medulla: catecholamines (epinephrine, norepinephrine, dopamine)."
  },
  {
   "id": "s10",
   "type": "text",
   "front": "Describe the HPA axis.",
   "back": "The paraventricular nucleus releases CRH, the major stimulus for ACTH from the anterior pituitary, which drives cortisol from the adrenal cortex. CRH integrates neural and hormonal signals. Circulating cortisol is the main inhibitor of CRH and ACTH, through gene expression."
  },
  {
   "id": "s11",
   "type": "text",
   "front": "Name the major brain structures in stress.",
   "back": "Cortex (especially prefrontal); limbic system: amygdala, hippocampus, hypothalamus (receiving PFC and amygdala input); brainstem: medulla (cardiovascular and respiratory responses), locus coeruleus (noradrenaline, arousal) and raphe nuclei (serotonin)."
  },
  {
   "id": "s12",
   "type": "text",
   "front": "Give the major effects of cortisol.",
   "back": "Metabolic: anti-insulin and permissive for glucagon and catecholamines. Vascular: permissive for catecholamines by raising alpha receptors. Immune: anti-inflammatory. Renal: regulates water excretion."
  },
  {
   "id": "h2",
   "type": "image",
   "target": "pituitary",
   "front": "Which gland is at the arrow, and what does it release in stress?",
   "back": "The pituitary: its anterior lobe releases ACTH, which drives cortisol."
  },
  {
   "id": "s13",
   "type": "text",
   "front": "How does stress interact with the immune system?",
   "back": "Psychoneuroimmunology studies these links. Stress can be pro- or anti-inflammatory via SAM or HPA. Glucocorticoids are first anti-inflammatory, then sensitise the immune response in recovery; CRH regulates immunity; the immune system in turn modulates the HPA axis. Endorphins rise and suppress immunity; growth hormone and prolactin fall."
  },
  {
   "id": "s14",
   "type": "text",
   "front": "How is the stress response terminated?",
   "back": "Cortisol feedback inhibits CRH and ACTH, and acts on the hippocampus, which turns off the HPA response via the PVN. Lesions along this circuit raise PVN CRH and prolong stress. Factors that damage the hippocampus raise glucocorticoids, which damage it further."
  },
  {
   "id": "s15",
   "type": "text",
   "front": "What is the brain-gut-microbiome axis?",
   "back": "Two-way communication between the brain and gut microbiota via neuroendocrine, neuroimmune and autonomic (vagal) pathways. Stress disturbs the gut ecosystem (for example IBS); gut infection can raise stress responsiveness and brain inflammation. The gut makes 95 percent of the body's serotonin."
  },
  {
   "id": "s16",
   "type": "text",
   "front": "Give the effects of chronic stress, part 1.",
   "back": "Chronic stress lasts longer than a month. Nervous and behavioural: dizziness, headache, somatic pain, anxiety, depression, aggression, cognitive impairment, stroke. Cardiovascular: coronary disease, infarction, heart failure, sudden death, tachycardia, dysrhythmias, hypertension. GI: acid and pepsin hypersecretion causing peptic ulcer and GERD. Immune dysfunction."
  },
  {
   "id": "s17",
   "type": "text",
   "front": "Give the effects of chronic stress, part 2.",
   "back": "Musculoskeletal: chronic pain, TMJ pain, worse arthritis. Respiratory: asthma, COPD. Reproductive: altered sex hormones and menses, infertility, impotence. Skin: worse lesions, rashes, itching, vasoconstriction and cold skin."
  },
  {
   "id": "s18",
   "type": "text",
   "front": "What does the biology of resilience show?",
   "back": "Resilience is a dynamic, lifelong continuum involving stress response systems, neural circuits and immune responses interacting with genes and environment. It involves active protective processes, not just the reversal of harm."
  }
 ],
 "deeper": [
  {
   "title": "Why chronic stress can shrink the hippocampus",
   "html": "<p>The hippocampus is the brake on the HPA axis, but it is also full of cortisol receptors. Sustained high cortisol damages it, which weakens the brake, which keeps cortisol high. The lecture describes exactly this vicious circle, and it helps explain the memory problems seen with long-term stress and depression.</p><p class='src'>Source: the lecture's termination of stress slide.</p>"
  },
  {
   "title": "Why stress can cause stomach ulcers",
   "html": "<p>Selye found bleeding ulcers in stressed animals, and the lecture lists acid and pepsin hypersecretion in chronic stress. Add the fight-or-flight drop in gut blood flow, which weakens the mucosa's defences, and the stomach lining is attacked while poorly protected.</p><p class='src'>Source: the lecture's general adaptation syndrome and chronic stress slides.</p>"
  }
 ],
