 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "What is required for vision?",
   "back": "An object, either a light source or a reflecting surface; light, within the purple to red range; and an eye with photoreceptors, which convert light into action potentials sent to the thalamus, visual cortex and subcortical areas."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "What governs refraction?",
   "back": "Rays travel straight within one medium and bend at a transparent surface. Refraction increases with the difference in refractive index between media and with deviation from a 90-degree angle; a perpendicular ray does not refract. Air has an index of 1."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Define dioptre.",
   "back": "Refractive power, the inverse of focal length in metres: a 50 cm lens is 2 D. Convex (converging) lenses are positive; concave (diverging) lenses are negative. The eye's lens is biconvex."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Name the four refraction points of the eye.",
   "back": "Air to anterior cornea; posterior cornea to aqueous humour; aqueous humour to lens; lens to vitreous humour. Two thirds of the refractive power is in the cornea."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Describe the corneal reflex.",
   "back": "Touch or dust on the richly innervated cornea is sensed by the trigeminal nerve, whose sensory nucleus synapses on the facial motor nucleus. The facial nerve closes the eye and increases lacrimation. A useful CNS test."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Describe the sclera, iris and pupil.",
   "back": "The sclera is protective fibrous tissue; only the cornea lets light in. The iris gives eye colour, with smooth muscle and pigment layers, and sets pupil diameter. Bright light gives miosis, darkness mydriasis. Sunglasses protect the photoreceptors."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "What is depth of focus?",
   "back": "A constricted pupil admits rays through a small area, which focus immediately, giving higher acuity. A dilated pupil scatters rays and blurs detail. The best acuity comes from rays within 5 degrees."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Trace the pupillary light reflex.",
   "back": "Optic nerve, pretectal area, Edinger-Westphal (parasympathetic) nucleus of CN III, ciliary ganglion, pupil constrictors. In the dark, the sympathetic system dilates the pupil via the cervical ganglion."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Direct versus consensual light reflex.",
   "back": "Light in one eye constricts that pupil (direct) and the other pupil (consensual or indirect), because the optic pathways decussate. A reflex in only one eye points to CN III. Loss of the reflex after head trauma suggests brainstem damage, near the vital centres."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "Describe the choroid and ciliary body.",
   "back": "The choroid is the vascular layer supplying the eye and helping keep its spherical shape. The ciliary body attaches to the zonular fibres that control lens shape and makes aqueous humour."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "Describe aqueous humour.",
   "back": "Filtered plasma from ciliary body epithelium, released into the anterior chamber and reabsorbed through the canal of Schlemm. It nourishes the lens and cornea and sets intraocular pressure, measured by tonometry."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "What is glaucoma?",
   "back": "Obstructed drainage, most often at the canal of Schlemm, raises aqueous volume and intraocular pressure. The pressure damages lens proteins and, reaching the retina, can cause loss of vision."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "Describe the vitreous humour and retinal detachment.",
   "back": "A semisolid jelly between lens and retina, present from birth and not renewed. Its fibres shape the eye and hold the retina against the choroid. If its collagen shortens, it pulls the retina off: retinal detachment, an emergency, most often after trauma."
  },
  {
   "id": "c13",
   "type": "text",
   "front": "Explain accommodation.",
   "back": "Ciliary muscle contraction relaxes the zonular fibres, so the lens thickens and refractive power rises: near vision, parasympathetic. Ciliary relaxation tenses the fibres and flattens the lens: distant vision. The near response also includes miosis and convergence."
  },
  {
   "id": "c14",
   "type": "text",
   "front": "Describe presbyopia and the refractive errors.",
   "back": "Presbyopia: lens proteins denature, the lens loses elasticity, near vision fails; accommodation nears zero after 70. Emmetropia: focus on the retina. Hyperopia: behind it; distance acuity can exceed 1. Myopia: in front. Astigmatism: uneven cornea or lens surface, corrected with cylindrical lenses."
  },
  {
   "id": "c15",
   "type": "text",
   "front": "How is visual acuity measured?",
   "back": "By two-point discrimination, which depends on optical, retinal and stimulus factors. Letter charts are read at 20 feet (6 m); normal is 20/20, or 1. Reading only the largest letter is 20/200."
  },
  {
   "id": "c16",
   "type": "text",
   "front": "Describe the macula, fovea and optic disc.",
   "back": "The macula and its central fovea give the highest acuity: 2 percent of the retina but a third of ganglion cells, cone-dominated, with fewer overlying layers. The optic disc, where the nerve leaves, has no photoreceptors: the blind spot, filled in by the other eye."
  },
  {
   "id": "c17",
   "type": "text",
   "front": "Name three fundus diseases.",
   "back": "Optic atrophy: ganglion cells degenerate, the disc becomes pale and large, possibly blindness. Papilloedema: raised intracranial pressure pushes the disc forward. Macular degeneration: loss of detailed vision."
  },
  {
   "id": "c18",
   "type": "text",
   "front": "Rods versus cones.",
   "back": "Cones: colour vision, high threshold, photopic, dense in the fovea and macula. Rods: black-and-white, scotopic dim-light vision, increasing toward the periphery."
  },
  {
   "id": "c19",
   "type": "text",
   "front": "Describe the retinal circuit.",
   "back": "Photoreceptors to bipolar cells to ganglion cells vertically. Horizontal cells carry signals sideways for lateral inhibition at the first synapse; amacrine cells do so at the second; interplexiform cells carry signals backwards to fine-tune lateral inhibition. Ganglion cells fire action potentials; their axons form the optic nerve, crossing at the chiasm. Y ganglion cells transmit fast warning signals."
  },
  {
   "id": "i20",
   "type": "image",
   "target": "fovea",
   "front": "Anatomy link: find the fovea.",
   "back": "The fovea in the macula, where cones dominate and acuity is highest."
  },
  {
   "id": "i21",
   "type": "image",
   "target": "ciliary",
   "front": "Anatomy link: which structure sets lens shape?",
   "back": "The ciliary body, via its muscle and the zonular fibres; it also makes aqueous humour."
  }
 ],
 "deeper": [
  {
   "title": "Why pupil checks are part of every head injury exam",
   "html": "<p>The light reflex runs through the midbrain, right beside the brainstem's vital centres. A pupil that stops reacting after head trauma can mean swelling is pressing on the brainstem or on CN III, which is why doctors shine a light in the eyes of every injured patient.</p><p class='src'>Source: the lecture's light reflex slides.</p>"
  },
  {
   "title": "Why reading glasses arrive in your forties",
   "html": "<p>Near vision needs the lens to round up when the ciliary muscle contracts. As lens proteins denature with age, the lens stiffens and can no longer round up enough, so near objects blur even though distance vision is fine. That is presbyopia, and convex reading lenses supply the missing power.</p><p class='src'>Source: the lecture's accommodation and presbyopia slides.</p>"
  }
 ],
