 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Why do taste and smell matter in medicine?",
   "back": "Many diseases have a characteristic smell or taste, such as sweet diabetic urine or lung cancer; some diseases damage smell, such as allergic rhinitis; electronic noses detect breath VOCs in lung cancer and MRSA. Chemosensory deficits harm nutrition and quality of life."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "How common are taste and smell disorders?",
   "back": "In the US, 7 million adults have taste and 14 million smell disorders; 1 to 2 percent report total loss of smell; 13.9 percent of institutionalised older adults versus 3.2 percent in the community; 400,000 doctor visits a year. Prevalence rises with age."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Name the basic tastes and their meaning.",
   "back": "Salty (NaCl): sodium and osmotic balance. Sweet (sucrose, sweeteners, some proteins): energy. Sour (HCl, tartaric acid): acids. Bitter (quinine): potential toxins. Umami (MSG): savoury, energy-rich food. Fat is a possible sixth taste."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Are taste responses innate?",
   "back": "Yes: newborns make different facial expressions to bitter and sweet tastants, so acceptance and rejection need no prior experience."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Where are taste buds located?",
   "back": "In papillae on the dorsal and lateral tongue, and on the soft palate, larynx, uvula, pharynx, epiglottis and upper oesophagus."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Describe taste transduction in general.",
   "back": "The chemical must dissolve in saliva and contact the gustatory hairs. Binding depolarises the taste cell, creating a generator potential; voltage-gated Na+, K+ and Ca2+ channels produce action potentials; Ca2+ influx triggers transmitter release. Each taste bud has about 100 cells and responds best to one taste but also to others."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Describe salty and sour transduction.",
   "back": "Salty: Na+ enters through a selective channel passing only Na+ and Li+, blocked by amiloride; the generator potential opens basolateral voltage-gated Na+ channels. Sour: H+ enters through PKD2L1, a TRP-type proton channel."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "How is taste coded?",
   "back": "There is evidence for both specific (labelled-line) and distributed coding; some suggest it works like colour vision. There is no agreed explanation yet."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "What shapes taste perception?",
   "back": "Other receptors, especially smell; the temperature and texture of food; and past experience with food. How the cortex processes taste is still unknown."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "Name the gustatory disorders.",
   "back": "Quantitative: ageusia (complete loss), hypogeusia (reduced), hypergeusia (enhanced), each total or partial. Qualitative: parageusia (distorted taste) and phantogeusia (persistent taste with no stimulus)."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "List causes of taste impairment.",
   "back": "Addison's disease, periodontal disease, oral infections such as thrush, upper respiratory infections, allergic rhinitis, head trauma, tumours such as vestibular schwannoma, Bell's palsy, vitamin and trace metal deficiencies, wisdom tooth extraction, MS, familial dysautonomia, cancer, radiation, chemotherapy and drugs. Widespread but uncommon."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "Describe olfaction in outline.",
   "back": "Olfactory receptor cells are neurons. Odorants bind receptors, afferent fibres carry signals to the olfactory bulb, the first central relay, then to central processing areas. Smells habituate rapidly."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "Can we smell disease?",
   "back": "Scrofula: stale beer. Typhoid: baked bread. Yellow fever: a butcher's shop. Diphtheria: sweet. Diabetic ketosis: decomposing apples. Failure to metabolise methionine: boiled cabbage. Hyperaminoaciduria: dried malt or hops."
  },
  {
   "id": "c13",
   "type": "text",
   "front": "Name the olfactory disorders.",
   "back": "Qualitative: parosmia (distorted), phantosmia (smell without odour), cacosmia (all odours unpleasant). Quantitative: normosmia, hyposmia (reduced), anosmia (complete or partial loss, acquired or congenital). Agnosia: odours detected but not classified."
  },
  {
   "id": "c14",
   "type": "text",
   "front": "How does ageing affect smell?",
   "back": "Sensitivity and discrimination decline, lowering quality of life, appetite and nutrition. Epithelial neurogenesis falls by about 90 percent in ageing mice; new bulb neurons from the subventricular zone, travelling the rostral migratory stream, also fall. If the basal cell layer survives injury, new cells can still be made."
  },
  {
   "id": "c15",
   "type": "text",
   "front": "Give the key messages on olfactory disorders.",
   "back": "They are common and increase with age. Causes: sinonasal disease, viral infection, head injury, toxins, drugs, autoimmune and neurodegenerative disease. Olfactory loss is an early sign of Parkinson's and Alzheimer's. Only nasal causes have causal treatment: surgery or corticosteroids."
  }
 ],
 "deeper": [
  {
   "title": "Why food tastes bland with a cold",
   "html": "<p>The lecture stresses that taste perception depends heavily on smell. With a blocked nose, odour molecules from food cannot reach the olfactory neurons, so only the five basic tastes remain, and most of what we call flavour disappears.</p><p class='src'>Source: the lecture's perception of taste slide.</p>"
  },
  {
   "title": "Why a smell test can help diagnose Parkinson's",
   "html": "<p>Olfactory loss often appears years before the tremor and stiffness of Parkinson's disease or the memory loss of Alzheimer's. Because it is cheap to test, a new unexplained loss of smell in an older adult can be an early clue worth following up.</p><p class='src'>Source: the lecture's key messages slide.</p>"
  }
 ],
