 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "How much filtrate do the kidneys form?",
   "back": "About 2 mL per second, 120 mL per minute, about 170 to 180 L per day, 50 to 60 times the blood volume. Only 1 to 2 L of urine leaves daily, so 99 percent is reabsorbed."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Give GFR values for men and women.",
   "back": "Men: about 125 mL/min or 180 L/day. Women: about 105 mL/min or 150 L/day."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Describe the three layers of the filtration barrier.",
   "back": "1. Fenestrated endothelium: 70 to 90 nm pores, excludes blood cells, highly permeable. 2. Basement membrane: negatively charged proteoglycan gel, repels albumin, excludes molecules above 8 nm. 3. Filtration slits: podocyte pedicels leave 30 nm negatively charged slits."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "What passes the filter, and what does not?",
   "back": "Molecules under about 3 nm pass freely: water, electrolytes, glucose, fatty acids, amino acids, nitrogenous wastes and vitamins. Small protein-bound substances such as calcium, iron and thyroid hormone do not. Plasma is 7 percent protein; filtrate 0.03 percent."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "What damages the filter, and what results?",
   "back": "Infection and trauma let albumin or blood cells through: proteinuria (albuminuria) and haematuria. Distance runners and swimmers can get temporary proteinuria or haematuria because strenuous exercise reduces renal perfusion and the glomerulus deteriorates under prolonged hypoxia."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Name the forces of glomerular filtration.",
   "back": "Favouring: glomerular blood hydrostatic pressure. Opposing: blood colloid osmotic pressure and capsular hydrostatic pressure. Textbook values: about 60, 32 and 18 mmHg, giving a net filtration pressure of about 10 mmHg."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Define GFR and Kf.",
   "back": "GFR is the filtrate formed per minute by both kidneys: GFR = NFP x Kf. Kf, the filtration coefficient, depends on the permeability and surface area of the barrier."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Why does hypertension harm the kidneys?",
   "back": "High glomerular pressure can rupture glomerular capillaries and cause scarring (nephrosclerosis) and atherosclerosis of renal vessels, ultimately leading to renal failure."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "How do arteriolar changes alter GFR?",
   "back": "Textbook physiology: afferent dilation or efferent constriction raises glomerular pressure and GFR; afferent constriction or efferent dilation lowers them."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "GFR too high versus too low.",
   "back": "Too high: fluid passes the tubules too fast to be reabsorbed, urine output rises, and dehydration and electrolyte depletion threaten. Too low: wastes are retained and azotemia may occur."
  }
 ],
 "deeper": [
  {
   "title": "Why protein in the urine points to kidney damage",
   "html": "<p>The basement membrane and podocyte slits are negatively charged, repelling negatively charged albumin. When disease disrupts these layers, albumin leaks through, which is why proteinuria is one of the earliest and most important signs of glomerular damage, for example in diabetic or hypertensive kidney disease.</p><p class='src'>Source: the lecture's filtration barrier slides.</p>"
  },
  {
   "title": "Why dehydration can make the kidneys fail",
   "html": "<p>Filtration depends on a net pressure of only about 10 mmHg. A fall in blood pressure from dehydration or bleeding cuts glomerular pressure, GFR falls, and wastes accumulate: azotemia. The kidneys defend GFR by adjusting their arterioles, but only up to a point.</p><p class='src'>Source: the lecture's filtration pressure and GFR regulation slides, with textbook values.</p>"
  }
 ],
